#!/usr/bin/env python3
"""Print-ready participant blanks and an offline host key, generated from the quiz."""
from pathlib import Path
import json,html
r=Path(__file__).resolve().parents[1];d=json.loads((r/'quiz-data.js').read_text().split('window.QUIZ_DATA = ')[1].rstrip(';\n'));esc=html.escape
head='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>{title}</title><style>@font-face{{font-family:Onest;src:url('../assets/fonts/Onest-Variable.ttf')}}*{{box-sizing:border-box}}body{{margin:0;background:#eee;color:#222;font:14px/1.4 Onest,sans-serif}}.sheet{{background:#fff;width:210mm;min-height:297mm;margin:12px auto;padding:19mm}}h1{{font-size:32px;line-height:1.1;margin:8px 0 12px;font-weight:500}}h2{{font-size:22px}}.eyebrow{{font-size:11px;letter-spacing:2px;color:#888;text-transform:uppercase}}.team{{margin:22px 0 28px;border-bottom:1px solid #999;padding-bottom:9px}}table{{width:100%;border-collapse:collapse}}th,td{{border-bottom:1px solid #ddd;padding:12px 8px;text-align:left}}td:first-child{{width:30px}}td:last-child{{width:65px;text-align:right;color:#777}}th{{font-weight:500;color:#777;font-size:12px}}.note{{color:#888;font-size:12px}}.total{{margin-top:24px;text-align:right}}.host{{width:min(1100px,95%);background:white;margin:20px auto;padding:35px}}article{{break-inside:avoid;border-bottom:1px solid #ddd;padding:22px 0}}article p{{white-space:pre-line}}.answer{{font-weight:500}}a{{color:#555}}.tools{{text-align:center;margin:20px}}button{{padding:10px 20px;border:0;border-radius:20px;cursor:pointer}}@page{{size:A4;margin:0}}@media print{{body{{background:white}}.sheet{{margin:0;break-after:page;min-height:297mm}}.sheet:last-child{{break-after:auto}}.host{{width:100%;padding:18mm;margin:0}}.tools{{display:none}}}}</style><body>'''
blanks=[];host=[]
for rd in d['rounds']:
 qs=[next(q for q in (d['warmup'] if rd['kind']=='warmup' else d['questions']) if q['id']==id) for id in rd['questionIds']]
 blanks.append('<section class="sheet"><div class="eyebrow">Культурный код · исторический квиз</div><h1>'+esc(rd['title'])+'</h1><p class="note">'+str(len(qs))+' вопросов · '+str(sum(q['value'] for q in qs))+' баллов максимум</p><div class="team">Команда: __________________________________________________</div><table><thead><tr><th>№</th><th>Ответ</th><th>Баллы</th></tr></thead><tbody>'+''.join('<tr><td>'+str(i+1)+'</td><td style="height:'+('9' if len(qs)==15 else '14')+'mm"></td><td>'+str(q['value'])+'</td></tr>' for i,q in enumerate(qs))+'</tbody></table><p class="total">Итого: __________</p><p class="note">В хронологии достаточно записать порядок букв. После блока — 30 секунд на сдачу.</p></section>')
 host.append('<h2>'+esc(rd['title'])+'</h2>')
 for i,q in enumerate(qs):host.append('<article><div class="eyebrow">Вопрос '+str(i+1)+' · '+str(q['value'])+' баллов</div><p>'+esc(q['text'])+'</p><p class="answer">'+esc(q['answer'])+'</p><p class="note">Зачёт: '+esc(q.get('acceptance','Ответ по существу; допустимы однозначные сокращения имён.'))+'</p></article>')
(r/'design/answer-sheets.html').write_text(head.format(title='Бланки · Культурный код')+'<div class="tools"><button onclick="print()">Печатать бланки</button></div>'+''.join(blanks)+'</body></html>')
(r/'design/host-answer-key.html').write_text(head.format(title='Ключ ведущего · Культурный код')+'<div class="tools"><button onclick="print()">Печатать ключ</button></div><main class="host"><div class="eyebrow">Только для ведущего</div><h1>Ключ и критерии зачёта</h1><p class="note">15 вопросов разминки + 6 блоков по 10. Ответы записываются в бланки. Каждый вопрос — 30 секунд после запуска кликом; на сдачу — 30 секунд. Максимум: 34 500 баллов.</p>'+''.join(host)+'</main></body></html>')
print('Built 7 A4 answer sheets and 75-answer host key.')
